tokens.customizationCode:
.nds-code-block-root {
  /* Altura máxima antes do scroll vertical */
  --code-block-max-block-size: 32rem;

  /* Destaque de linha em outra cor semântica */
  --code-block-highlight-bg: hsl(var(--warning) / 0.16);
  --code-block-highlight-accent: hsl(var(--warning));
}

/* Paleta de sintaxe: sobrescreva só o que precisar */
.dark .nds-code-block-root {
  --code-token-comment: hsl(0 0% 74%);
}

.nds-code-block-root {
  /* Maximum height before vertical scrolling */
  --code-block-max-block-size: 32rem;

  /* Line highlight in another semantic color */
  --code-block-highlight-bg: hsl(var(--warning) / 0.16);
  --code-block-highlight-accent: hsl(var(--warning));
}

/* Syntax palette: override only what you need */
.dark .nds-code-block-root {
  --code-token-comment: hsl(0 0% 74%);
}

.nds-code-block-root {
  /* Altura máxima antes del scroll vertical */
  --code-block-max-block-size: 32rem;

  /* Destaque de línea en otro color semántico */
  --code-block-highlight-bg: hsl(var(--warning) / 0.16);
  --code-block-highlight-accent: hsl(var(--warning));
}

/* Paleta de sintaxis: sobrescribe solo lo necesario */
.dark .nds-code-block-root {
  --code-token-comment: hsl(0 0% 74%);
}
